import { request } from '@/request/request.js';

export const listRegion = () => {
    return Promise.resolve({ data: [] })
}

export const xcxLogin = (params) => {
    return request({
        url: '/xcxLogin',
        method: 'post',
        data: params,
        header: { 'Content-Type': 'application/x-www-form-urlencoded' }
    })
}

export const getInfo = () => {
    return request({
        url: '/getInfo',
        method: 'get'
    })
}
